using System.Text.Json;

namespace OpenVector.RawAccel.Tests;

/// <summary>Loads Golden/golden.json (generated by Golden/generate_golden.py from fit_rawaccel.py).</summary>
internal static class Golden
{
    private static readonly Lazy<JsonDocument> Doc = new(() =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "Golden", "golden.json"))));

    public static JsonElement Root => Doc.Value.RootElement;

    public static double D(this JsonElement e, string name) => e.GetProperty(name).GetDouble();
    public static double[] Arr(this JsonElement e, string name) => e.GetProperty(name).EnumerateArray().Select(x => x.GetDouble()).ToArray();

    public static double[] Theta(int n) => Enumerable.Range(0, n).Select(i => 2 * Math.PI * i / n).ToArray();
}
